mapper.sql:
	FROM product a
	WHERE 1=1
		AND a.ifprdelNy=0

		AND a.ifpruseNy = #{shUseNy}
        AND a.ifprdelNy = #{shDelNy}



					AND a.ifprdate BETWEEN #{shDateStartdb} AND #{shDateEnddb}

					AND a.ifprredate BETWEEN #{shDateStartdb} AND #{shDateEnddb}


            AND a.ifprcategory = #{shValue}
            AND a.ifprtitle LIKE CONCAT('%',#{shValue},'%')
            AND a.ifprtypeNy LIKE CONCAT('%',#{shValue},'%')
